"""Hidden behavioral tests for cmark: render_xml. Generated by pbkit from the gold binary."""


def test_kitchen_sink_xml(run):
    r = run(args=['-t', 'xml'], stdin=b'# Heading *one*\n\nSetext heading\n--------------\n\nA paragraph with *emph*, **strong**, ***both***, `code`, a [link](http://example.com "Title"),\nan ![image](img.png "Img"), <http://auto.link>, <me@example.com>, a hard\\\nbreak and a soft\nbreak. Entities: &copy; &#x27; &#39; &nbsp;. Backslash \\* escapes.\n\n> A block quote\n> with *two* lines\n>\n> > nested quote\n\n1. first\n2. second\n   - nested bullet\n   - another\n\n     with a paragraph\n3. third\n\n- [ ] not a task list\n* different bullet\n\n```python\ndef f(x):\n    return x * 2\n```\n\n    indented code block\n\n<div class="raw">\n*not emph*\n</div>\n\nInline <span>html</span> and <!-- comment -->.\n\n***\n\n[ref link][ref] and [collapsed][] and [shortcut].\n\n[ref]: /url "ref title"\n[collapsed]: </with spaces>\n[shortcut]: http://x.y \'single\'\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <heading level="1">\n    <text xml:space="preserve">Heading </text>\n    <emph>\n      <text xml:space="preserve">one</text>\n    </emph>\n  </heading>\n  <heading level="2">\n    <text xml:space="preserve">Setext heading</text>\n  </heading>\n  <paragraph>\n    <text xml:space="preserve">A paragraph with </text>\n    <emph>\n      <text xml:space="preserve">emph</text>\n    </emph>\n    <text xml:space="preserve">, </text>\n    <strong>\n      <text xml:space="preserve">strong</text>\n    </strong>\n    <text xml:space="preserve">, </text>\n    <emph>\n      <strong>\n        <text xml:space="preserve">both</text>\n      </strong>\n    </emph>\n    <text xml:space="preserve">, </text>\n    <code xml:space="preserve">code</code>\n    <text xml:space="preserve">, a </text>\n    <link destination="http://example.com" title="Title">\n      <text xml:space="preserve">link</text>\n    </link>\n    <text xml:space="preserve">,</text>\n    <softbreak />\n    <text xml:space="preserve">an </text>\n    <image destination="img.png" title="Img">\n      <text xml:space="preserve">image</text>\n    </image>\n    <text xml:space="preserve">, </text>\n    <link destination="http://auto.link">\n      <text xml:space="preserve">http://auto.link</text>\n    </link>\n    <text xml:space="preserve">, </text>\n    <link destination="mailto:me@example.com">\n      <text xml:space="preserve">me@example.com</text>\n    </link>\n    <text xml:space="preserve">, a hard</text>\n    <linebreak />\n    <text xml:space="preserve">break and a soft</text>\n    <softbreak />\n    <text xml:space="preserve">break. Entities: \xc2\xa9 \' \' \xc2\xa0. Backslash * escapes.</text>\n  </paragraph>\n  <block_quote>\n    <paragraph>\n      <text xml:space="preserve">A block quote</text>\n      <softbreak />\n      <text xml:space="preserve">with </text>\n      <emph>\n        <text xml:space="preserve">two</text>\n      </emph>\n      <text xml:space="preserve"> lines</text>\n    </paragraph>\n    <block_quote>\n      <paragraph>\n        <text xml:space="preserve">nested quote</text>\n      </paragraph>\n    </block_quote>\n  </block_quote>\n  <list type="ordered" start="1" delim="period" tight="true">\n    <item>\n      <paragraph>\n        <text xml:space="preserve">first</text>\n      </paragraph>\n    </item>\n    <item>\n      <paragraph>\n        <text xml:space="preserve">second</text>\n      </paragraph>\n      <list type="bullet" tight="false">\n        <item>\n          <paragraph>\n            <text xml:space="preserve">nested bullet</text>\n          </paragraph>\n        </item>\n        <item>\n          <paragraph>\n            <text xml:space="preserve">another</text>\n          </paragraph>\n          <paragraph>\n            <text xml:space="preserve">with a paragraph</text>\n          </paragraph>\n        </item>\n      </list>\n    </item>\n    <item>\n      <paragraph>\n        <text xml:space="preserve">third</text>\n      </paragraph>\n    </item>\n  </list>\n  <list type="bullet" tight="true">\n    <item>\n      <paragraph>\n        <text xml:space="preserve">[ ] not a task list</text>\n      </paragraph>\n    </item>\n  </list>\n  <list type="bullet" tight="true">\n    <item>\n      <paragraph>\n        <text xml:space="preserve">different bullet</text>\n      </paragraph>\n    </item>\n  </list>\n  <code_block info="python" xml:space="preserve">def f(x):\n    return x * 2\n</code_block>\n  <code_block xml:space="preserve">indented code block\n</code_block>\n  <html_block xml:space="preserve">&lt;div class=&quot;raw&quot;&gt;\n*not emph*\n&lt;/div&gt;\n</html_block>\n  <paragraph>\n    <text xml:space="preserve">Inline </text>\n    <html_inline xml:space="preserve">&lt;span&gt;</html_inline>\n    <text xml:space="preserve">html</text>\n    <html_inline xml:space="preserve">&lt;/span&gt;</html_inline>\n    <text xml:space="preserve"> and </text>\n    <html_inline xml:space="preserve">&lt;!-- comment --&gt;</html_inline>\n    <text xml:space="preserve">.</text>\n  </paragraph>\n  <thematic_break />\n  <paragraph>\n    <link destination="/url" title="ref title">\n      <text xml:space="preserve">ref link</text>\n    </link>\n    <text xml:space="preserve"> and </text>\n    <link destination="/with spaces">\n      <text xml:space="preserve">collapsed</text>\n    </link>\n    <text xml:space="preserve"> and </text>\n    <link destination="http://x.y" title="single">\n      <text xml:space="preserve">shortcut</text>\n    </link>\n    <text xml:space="preserve">.</text>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_lists_xml(run):
    r = run(args=['-t', 'xml'], stdin=b'- a\n- b\n\n- c\n\n1) x\n2) y\n\n10. ten\n11. eleven\n\n* loose\n\n  para\n* tight\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <list type="bullet" tight="false">\n    <item>\n      <paragraph>\n        <text xml:space="preserve">a</text>\n      </paragraph>\n    </item>\n    <item>\n      <paragraph>\n        <text xml:space="preserve">b</text>\n      </paragraph>\n    </item>\n    <item>\n      <paragraph>\n        <text xml:space="preserve">c</text>\n      </paragraph>\n    </item>\n  </list>\n  <list type="ordered" start="1" delim="paren" tight="true">\n    <item>\n      <paragraph>\n        <text xml:space="preserve">x</text>\n      </paragraph>\n    </item>\n    <item>\n      <paragraph>\n        <text xml:space="preserve">y</text>\n      </paragraph>\n    </item>\n  </list>\n  <list type="ordered" start="10" delim="period" tight="true">\n    <item>\n      <paragraph>\n        <text xml:space="preserve">ten</text>\n      </paragraph>\n    </item>\n    <item>\n      <paragraph>\n        <text xml:space="preserve">eleven</text>\n      </paragraph>\n    </item>\n  </list>\n  <list type="bullet" tight="false">\n    <item>\n      <paragraph>\n        <text xml:space="preserve">loose</text>\n      </paragraph>\n      <paragraph>\n        <text xml:space="preserve">para</text>\n      </paragraph>\n    </item>\n    <item>\n      <paragraph>\n        <text xml:space="preserve">tight</text>\n      </paragraph>\n    </item>\n  </list>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_quotes_and_dashes_xml(run):
    r = run(args=['-t', 'xml'], stdin=b'"Hello," said the spider. \'Shelob\' is my name -- or --- maybe... it\'s 1990\'s.\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <paragraph>\n    <text xml:space="preserve">&quot;Hello,&quot; said the spider. \'Shelob\' is my name -- or --- maybe... it\'s 1990\'s.</text>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_special_chars_xml(run):
    r = run(args=['-t', 'xml'], stdin=b'Special: \\ { } $ & # ^ _ % ~ < > " \' | and . at line start\n\n.SH not a macro\n\'quote\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <paragraph>\n    <text xml:space="preserve">Special: \\ { } $ &amp; # ^ _ % ~ &lt; &gt; &quot; \' | and . at line start</text>\n  </paragraph>\n  <paragraph>\n    <text xml:space="preserve">.SH not a macro</text>\n    <softbreak />\n    <text xml:space="preserve">\'quote</text>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


