def test_code_xml(run):
    r = run(args=['-t', 'xml'], stdin=b'``` js {.class}\nconsole.log(`x`);\n```\n\n~~~~\n~~~\n~~~~\n\n`` a`b ``\n\n````\n```\n````\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <code_block info="js {.class}" xml:space="preserve">console.log(`x`);\n</code_block>\n  <code_block xml:space="preserve">~~~\n</code_block>\n  <paragraph>\n    <code xml:space="preserve">a`b</code>\n  </paragraph>\n  <code_block xml:space="preserve">```\n</code_block>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


